function validate([n, highways, discounts]) {
  if (!Number.isInteger(n) || n < 2 || n > 1000) return 'n must be between 2 and 1000.';
  if (!Array.isArray(highways) || highways.length < 1 || highways.length > 1000) return 'highways needs 1 to 1000 roads.';
  const seen = new Set();
  for (const road of highways) {
    if (!Array.isArray(road) || road.length !== 3) return 'Each highway is [city1, city2, toll].';
    const [a, b, toll] = road;
    if (![a, b, toll].every(Number.isInteger)) return 'Highway values must be integers.';
    if (a < 0 || a >= n || b < 0 || b >= n) return 'Cities must be between 0 and n - 1.';
    if (a === b) return 'A highway joins two different cities.';
    if (toll < 0 || toll > 100000) return 'toll must be between 0 and 100000.';
    const key = Math.min(a, b) * 1000 + Math.max(a, b);
    if (seen.has(key)) return 'Two highways join the same pair of cities.';
    seen.add(key);
  }
  if (!Number.isInteger(discounts) || discounts < 0 || discounts > 500) return 'discounts must be between 0 and 500.';
  return null;
}

