function minimumCost(n, highways, discounts) {
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b, toll] of highways) {
    graph[a].push([b, toll]);
    graph[b].push([a, toll]);
  }
  const fewestUsed = new Array(n).fill(Infinity);
  const heap = [];
  const push = (entry) => {
    heap.push(entry);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent][0] <= heap[child][0]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let parent = 0;
      while (true) {
        let smallest = parent;
        const left = 2 * parent + 1;
        const right = left + 1;
        if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
        if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
        if (smallest === parent) break;
        [heap[parent], heap[smallest]] = [heap[smallest], heap[parent]];
        parent = smallest;
      }
    }
    return top;
  };
  push([0, 0, 0]);
  while (heap.length > 0) {
    const [cost, city, used] = pop();
    if (used >= fewestUsed[city]) continue;
    fewestUsed[city] = used;
    if (city === n - 1) return cost;
    for (const [next, toll] of graph[city]) {
      if (used < fewestUsed[next]) push([cost + toll, next, used]);
      if (used < discounts && used + 1 < fewestUsed[next]) push([cost + Math.floor(toll / 2), next, used + 1]);
    }
  }
  return -1;
}

