function minimumCost(n, highways, discounts) {
  // Enumerate every simple path from 0 to n - 1; on a path, the coupons go on the largest tolls.
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b, t] of highways) { adj[a].push([b, t]); adj[b].push([a, t]); }
  let answer = -1;
  const onPath = new Array(n).fill(false);
  const tolls = [];
  const dfs = (city) => {
    if (city === n - 1) {
      const sorted = [...tolls].sort((x, y) => y - x);
      let total = 0;
      sorted.forEach((t, idx) => { total += idx < discounts ? Math.floor(t / 2) : t; });
      if (answer === -1 || total < answer) answer = total;
      return;
    }
    onPath[city] = true;
    for (const [next, t] of adj[city]) {
      if (onPath[next]) continue;
      tolls.push(t);
      dfs(next);
      tolls.pop();
    }
    onPath[city] = false;
  };
  dfs(0);
  return answer;
}

