function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const small = size === 'small';
  const n = small ? int(2, 7) : int(600, 1000);
  const maxEdges = small ? Math.min(n * (n - 1) / 2, int(1, 10)) : 1000;
  const maxToll = small ? (rand() < 0.5 ? 9 : 40) : 100000;
  // Shape 0: random roads only (small inputs), 1: a random tree plus extra roads, 2: a long chain plus extra roads.
  const shape = small ? (rand() < 0.4 ? 0 : int(1, 2)) : (rand() < 0.3 ? 2 : 1);
  const seen = new Set();
  const highways = [];
  const add = (a, b) => {
    if (a === b || highways.length >= maxEdges) return;
    const key = Math.min(a, b) * 1000 + Math.max(a, b);
    if (seen.has(key)) return;
    seen.add(key);
    highways.push(rand() < 0.5 ? [a, b, int(0, maxToll)] : [b, a, int(0, maxToll)]);
  };
  if (shape > 0) {
    // A random tree or a chain links the cities; now and then one city is left out so the target may be unreachable.
    const order = Array.from({ length: n }, (_, i) => i);
    for (let i = n - 1; i > 0; i--) { const j = int(0, i); [order[i], order[j]] = [order[j], order[i]]; }
    const wide = rand() < 0.5;
    const linked = !small && rand() < 0.15 ? n - 2 : n - 1;
    for (let i = 1; i <= linked; i++) add(order[i], shape === 2 ? order[i - 1] : order[wide ? int(0, i - 1) : int(Math.max(0, i - 3), i - 1)]);
  }
  let guard = 0;
  while (highways.length < maxEdges && guard++ < 100000) add(int(0, n - 1), int(0, n - 1));
  // Long chains have long paths, so they get fewer coupons to keep the search fast.
  const discounts = small ? int(0, 4) : shape === 2 ? int(0, 25) : int(0, 500);
  return [n, highways, discounts];
}
